#include <limits.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum { LEAF_MAX = 4, LEAF_POOL = 8 };
typedef struct Leaf {
  int key[LEAF_MAX], value[LEAF_MAX];
  size_t n;
  bool used;
  struct Leaf *next;
} Leaf;
typedef struct {
  Leaf pages[LEAF_POOL];
  Leaf *child[LEAF_POOL];
  size_t n;
} BTree;
void tree_init(BTree *t) {
  memset(t, 0, sizeof *t);
  t->n = 1;
  t->pages[0].used = true;
  t->child[0] = &t->pages[0];
}
size_t route(const BTree *t, int key) {
  size_t i = 0;
  while (i + 1 < t->n && t->child[i + 1]->key[0] <= key)
    ++i;
  return i;
}
bool tree_find(const BTree *t, int key, int *out) {
  const Leaf *p = t->child[route(t, key)];
  for (size_t i = 0; i < p->n; ++i)
    if (p->key[i] == key) {
      *out = p->value[i];
      return true;
    }
  return false;
}
bool tree_put(BTree *t, int key, int value) {
  size_t at = route(t, key);
  Leaf *p = t->child[at];
  int old;
  if (tree_find(t, key, &old))
    return false;
  if (p->n < LEAF_MAX) {
    size_t i = p->n++;
    while (i && p->key[i - 1] > key) {
      p->key[i] = p->key[i - 1];
      p->value[i] = p->value[i - 1];
      --i;
    }
    p->key[i] = key;
    p->value[i] = value;
    return true;
  }
  if (t->n == LEAF_POOL)
    return false;
  Leaf *right = NULL;
  for (size_t i = 0; i < LEAF_POOL; ++i)
    if (!t->pages[i].used) {
      right = &t->pages[i];
      break;
    }
  if (!right)
    return false;
  int keys[5], values[5];
  size_t j = 0;
  bool added = false;
  for (size_t i = 0; i < 5; ++i) {
    if (!added && (j == p->n || key < p->key[j])) {
      keys[i] = key;
      values[i] = value;
      added = true;
    } else {
      keys[i] = p->key[j];
      values[i] = p->value[j++];
    }
  }
  *right = (Leaf){0};
  right->used = true;
  p->n = 2;
  right->n = 3;
  for (size_t i = 0; i < 2; ++i) {
