  FILE *f = tmpfile();
  if (!f)
    return 1;
  unsigned char header[8] = {0x54, 0x44, 0x42, 0x31, 99, 40, 0, 0};
  if (fwrite(header, 1, 8, f) != 8 || fseek(f, 0, SEEK_SET)) {
    fclose(f);
    return 1;
