unsigned factorial_loop(unsigned n) {
  unsigned result = 1;
  for (unsigned i = 2; i <= n; ++i)
    result *= i;
  return result;
}

int main(void) {
  printf("recursive=%u iterative=%u\n", factorial(6), factorial_loop(6));
