void merge_sort(int *a, int *tmp, size_t n) {
  if (n < 2)
    return;
  size_t m = n / 2;
  merge_sort(a, tmp, m);
  merge_sort(a + m, tmp + m, n - m);
  size_t i = 0, j = m, k = 0;
  while (i < m && j < n)
    tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
  while (i < m)
    tmp[k++] = a[i++];
  while (j < n)
    tmp[k++] = a[j++];
  for (k = 0; k < n; ++k)
    a[k] = tmp[k];
}

