}
void quick(int *a, size_t n) {
  if (n < 2)
    return;
  int pivot = a[n - 1];
  size_t boundary = 0;
  for (size_t j = 0; j + 1 < n; ++j)
    if (a[j] < pivot) {
      int t = a[j];
      a[j] = a[boundary];
      a[boundary++] = t;
    }
  a[n - 1] = a[boundary];
  a[boundary] = pivot;
  quick(a, boundary);
  quick(a + boundary + 1, n - boundary - 1);
}

int main(void) {
  int a[] = {5, 2, 4, 1, 3};
  quick(a, 5);
  show(a, 5);
  return 0;
}

