  int a[] = {INT_MAX, -7, 0, INT_MIN};
  qsort(a, 4, sizeof a[0], compare_int);
  printf("ordered=%d extremes=%d\n",
         a[0] <= a[1] && a[1] <= a[2] && a[2] <= a[3],
