bool subset(const int *a, size_t n, size_t i, int remaining) {
  if (remaining == 0)
    return true;
  if (i == n || remaining < 0)
    return false;
  return subset(a, n, i + 1, remaining - a[i]) ||
         subset(a, n, i + 1, remaining);
}

